import sys
import json
import termios
import tty
import os
import shutil

# ANSI colors
RESET = "\033[0m"
BOLD = "\033[1m"
INVERSE = "\033[7m"
GRAY = "\033[90m"
RED = "\033[91m"
GREEN = "\033[92m"
YELLOW = "\033[93m"
BLUE = "\033[94m"
CYAN = "\033[96m"

def sort_json(data):
    if isinstance(data, dict):
        return {k: sort_json(v) for k, v in sorted(data.items())}
    if isinstance(data, list):
        return [sort_json(v) for v in data]
    return data

class State:
    def __init__(self, data):
        self.data = data
        self.expanded = {()} # Set of paths
        self.table_view = set() # Set of paths
        self.selected_line = 0
        self.scroll_top = 0
        self.fullscreen = False

        # Default expansion: level 1 objects
        if isinstance(data, dict):
            for k in data:
                self.expanded.add((k,))

    def toggle_expanded(self, path):
        if path in self.expanded:
            self.expanded.remove(path)
        else:
            self.expanded.add(path)

    def toggle_table_view(self, path):
        if path in self.table_view:
            self.table_view.remove(path)
        else:
            self.table_view.add(path)

def get_text_for_value(val):
    if val is None:
        return RED + "null" + RESET
    if isinstance(val, bool):
        return YELLOW + str(val).lower() + RESET
    if isinstance(val, (int, float)):
        return CYAN + str(val) + RESET
    if isinstance(val, str):
        return GREEN + json.dumps(val) + RESET
    return ""

def flatten(data, path, depth, is_last, state, lines):
    # This function should add lines to the 'lines' list.
    # Each line: { 'text': ..., 'path': ..., 'selectable_range': (start, end), 'type': ... }
    indent = "  " * depth
    suffix = "" if is_last else ","

    if isinstance(data, dict):
        opening = "{"
        if path in state.expanded:
            lines.append({
                'text': f"{indent}{BOLD}{opening}{RESET}",
                'path': path,
                'selectable_range': (len(indent), len(indent)+1),
                'type': 'object_start'
            })
            items = list(data.items())
            for i, (k, v) in enumerate(items):
                is_last_item = (i == len(items) - 1)
                child_path = path + (k,)
                child_indent = "  " * (depth + 1)
                key_str = f"{child_indent}{BLUE}{json.dumps(k)}{RESET}: "

                if isinstance(v, (dict, list)):
                    # Check for table view option
                    tv_option = ""
                    if isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                        tv_option = f"   {GRAY}(table view){RESET}"

                    if child_path in state.expanded:
                        lines.append({
                            'text': f"{key_str}{BOLD}{'{' if isinstance(v, dict) else '['}{RESET}{tv_option}",
                            'path': child_path,
                            'selectable_range': (len(child_indent) + len(json.dumps(k)) + 2, len(child_indent) + len(json.dumps(k)) + 3),
                            'type': 'node_start',
                            'tv_range': (len(key_str) + 3, len(key_str) + 3 + 12) if tv_option else None
                        })
                        flatten(v, child_path, depth + 1, True, state, lines)
                        lines[-1]['text'] += "," if not is_last_item else ""
                    else:
                        collapsed = "{...}" if isinstance(v, dict) else "[...]"
                        lines.append({
                            'text': f"{key_str}{BOLD}{collapsed}{RESET}{suffix if is_last_item else ','}{tv_option}",
                            'path': child_path,
                            'selectable_range': (len(child_indent) + len(json.dumps(k)) + 2, len(child_indent) + len(json.dumps(k)) + 2 + len(collapsed)),
                            'type': 'node_collapsed',
                            'tv_range': (len(key_str) + len(collapsed) + 3, len(key_str) + len(collapsed) + 3 + 12) if tv_option else None
                        })
                else:
                    val_str = get_text_for_value(v)
                    lines.append({
                        'text': f"{key_str}{val_str}{',' if not is_last_item else ''}",
                        'path': child_path,
                        'selectable_range': (len(key_str), len(key_str) + len(val_str) - len(RESET) - len(GREEN if isinstance(v, str) else (CYAN if isinstance(v, (int, float)) else (YELLOW if isinstance(v, bool) else RED)))),
                        'type': 'scalar'
                    })
            lines.append({
                'text': f"{indent}{BOLD}}}{RESET}{suffix}",
                'path': None, # Not selectable
            })
        else:
            # Collapsed object
            lines.append({
                'text': f"{indent}{BOLD}{{...}}{RESET}{suffix}",
                'path': path,
                'selectable_range': (len(indent), len(indent)+5),
                'type': 'node_collapsed'
            })
    # Similar for list...
    # ...

EOF
