import sys
import json
import termios
import tty
import os
import shutil

# ANSI codes
RESET = "\033[0m"
BOLD = "\033[1m"
INVERSE = "\033[7m"
GRAY = "\033[90m"
RED = "\033[91m"
GREEN = "\033[92m"
YELLOW = "\033[93m"
BLUE = "\033[94m"
CYAN = "\033[96m"
CYAN_DARK = "\033[36m"

def getch():
    fd = sys.stdin.fileno()
    old_settings = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        ch = sys.stdin.read(1)
        if ch == '\x1b':
            ch2 = sys.stdin.read(1)
            if ch2 == '[':
                ch += ch2
                while True:
                    c = sys.stdin.read(1)
                    ch += c
                    if c in 'ABCDEFGHJKMNRSTVZcfghilmnpqrstuwxy~':
                        break
            else:
                ch += ch2
        return ch
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)

def sort_json(data):
    if isinstance(data, dict):
        return {k: sort_json(v) for k, v in sorted(data.items())}
    if isinstance(data, list):
        return [sort_json(v) for v in data]
    return data

class State:
    def __init__(self, data):
        self.data = data
        self.expanded = set([()]) # Paths
        self.table_view = set() # Paths
        self.selected_row = 0
        self.selected_col = 0 # For table view
        self.scroll_top = 0
        self.fullscreen = False
        self.lines = []

        # Default expansion
        if isinstance(data, dict):
            for k in data:
                self.expanded.add((k,))
        elif isinstance(data, list):
            # Arrays are collapsed by default in the original? 
            # Let's check: "tags": [...] was collapsed.
            pass

def get_value_color(val):
    if val is None: return RED
    if isinstance(val, bool): return YELLOW
    if isinstance(val, (int, float)): return CYAN
    if isinstance(val, str): return GREEN
    return ""

def format_value(val):
    if val is None: return "null"
    if isinstance(val, bool): return str(val).lower()
    if isinstance(val, (int, float)): return str(val)
    if isinstance(val, str): return json.dumps(val)
    return ""

def wrap_text(text, width, indent):
    if len(text) <= width:
        return [text]
    lines = []
    while text:
        if not lines:
            lines.append(text[:width])
            text = text[width:]
        else:
            lines.append(text[:width-indent])
            text = text[width-indent:]
    return lines

def flatten_tree(data, path, depth, is_last, state, lines):
    indent_str = "  " * depth
    suffix = "" if is_last else ","

    if isinstance(data, dict):
        opening = "{"
        closing = "}"
        if path in state.expanded:
            lines.append({
                'pieces': [(indent_str, ""), (opening, BOLD)],
                'path': path,
                'selectable_piece': 1,
                'type': 'object_start'
            })
            items = list(data.items())
            for i, (k, v) in enumerate(items):
                is_last_item = (i == len(items) - 1)
                child_path = path + (k,)
                child_indent = "  " * (depth + 1)
                key_part = f"{child_indent}{BLUE}{json.dumps(k)}{RESET}: "

                if isinstance(v, (dict, list)):
                    tv_option = (isinstance(v, list) and v and all(isinstance(x, dict) for x in v))
                    char = "{" if isinstance(v, dict) else "["
                    if child_path in state.expanded:
                        line = {
                            'pieces': [(child_indent, ""), (json.dumps(k), BLUE), (": ", ""), (char, BOLD)],
                            'path': child_path,
                            'selectable_piece': 3,
                            'type': 'node_start'
                        }
                        if tv_option:
                            line['pieces'].append(("   ", ""))
                            line['pieces'].append(("(table view)", GRAY))
                            line['tv_piece'] = 5
                        lines.append(line)
                        flatten_tree(v, child_path, depth + 1, True, state, lines)
                        lines[-1]['pieces'].append(("," if not is_last_item else "", ""))
                    else:
                        collapsed = "{...}" if isinstance(v, dict) else "[...]"
