    num_visible = min(len(visible_lines), term_height)

    if state.selected_row < state.scroll_top:
        state.scroll_top = state.selected_row
    elif state.selected_row >= state.scroll_top + num_visible:
        state.scroll_top = state.selected_row - num_visible + 1

    output = []
    for i in range(state.scroll_top, min(state.scroll_top + num_visible, len(visible_lines))):
        line_data = visible_lines[i]
        is_selected = (i == state.selected_row)

        line_str = ""
        for j, (text, color) in enumerate(line_data['pieces']):
            piece_selected = False
            if is_selected:
                if 'selectable_piece' in line_data and j == line_data['selectable_piece'] and state.selected_col == 0:
                    piece_selected = True
                elif 'tv_piece' in line_data and j == line_data['tv_piece'] and state.selected_col == 1:
