            render(state)
            out, h = display(state)
            if last_h > 0:
                sys.stdout.write(f"\033[{last_h-1}A\r")
            sys.stdout.write(out + "\r")
            sys.stdout.flush()
            last_h = h

            ch = getch()
            if ch in ('q', '\x1b'):
                break
            elif ch in ('j', '\x1b[B'): # Down
                if state.selected_row < len(state.lines) - 1:
                    state.selected_row += 1
                    state.selected_col = 0
            elif ch in ('k', '\x1b[A'): # Up
                if state.selected_row > 0:
                    state.selected_row -= 1
                    state.selected_col = 0
            elif ch in ('h', '\x1b[D'): # Left
                if state.selected_col > 0:
                    state.selected_col -= 1
            elif ch in ('l', '\x1b[C'): # Right
                line = state.lines[state.selected_row]
                if 'tv_piece' in line and state.selected_col == 0:
                    state.selected_col = 1
                elif 'selectable_pieces' in line and state.selected_col < len(line['selectable_pieces']) - 1:
                    state.selected_col += 1
            elif ch == '\r': # Enter
                line = state.lines[state.selected_row]
                if state.selected_col == 1 and 'tv_piece' in line:
                    state.toggle_table_view(line['path'])
                elif 'type' in line and line['type'] == 'table_header':
                    state.toggle_table_view(line['path'])
                elif 'path' in line and line['path'] is not None:
                    state.toggle_expanded(line['path'])
            elif ch == 'G': # Bottom
                state.selected_row = len(state.lines) - 1
            elif ch == 'g': # gg
                ch2 = getch()
                if ch2 == 'g':
                    state.selected_row = 0
            elif ch == '+': # Deep expand
                # Just expand all for now
                def expand_all(d, p):
                    state.expanded.add(p)
                    if isinstance(d, dict):
                        for k, v in d.items(): expand_all(v, p + (k,))
                    elif isinstance(d, list):
                        for i, v in enumerate(d): expand_all(v, p + (i,))
                expand_all(state.data, ())
            elif ch == '-': # Deep collapse
                state.expanded = {()}
    finally:
        if state.fullscreen:
            sys.stdout.write("\033[?1049l")
        else:
            sys.stdout.write("\n")

if __name__ == "__main__":
    main()
